new='''/**
 * What the query language itself yielded: unlike `ParsedSearchQuery`, `kinds`
 * holds only the kinds named by `kind:` / `in:` tokens and is empty when there
 * were none, so a caller can tell "asked for issues" from "asked for nothing".
 */
export interface SearchQueryTokens {
  readonly text: string;
  readonly kinds: readonly SearchSubjectKind[];
  readonly projectId: ProjectId | null;
  readonly unknownTokens: readonly string[];
}

/**
 * The one parser behind the dialog's hint line and the server's query
 * execution (ADR 0007).
 *
 * @param raw      what the user typed
 * @param advanced whether the `advanced_search` flag is on for this org; when
 *                 false the whole string is treated as free text so a colon in
 *                 a title still finds the title.
 */
export function scanSearchQuery(
  raw: string,
  advanced: boolean,
): SearchQueryTokens {
  if (!advanced) {
    return {
      text: raw.trim(),
      kinds: [],
      projectId: null,
      unknownTokens: [],
    };
  }

  const terms: string[] = [];
  const kinds: SearchSubjectKind[] = [];
  const unknown: string[] = [];
  let projectId: ProjectId | null = null;

  for (const token of raw.split(/\\s+/).filter((part) => part.length > 0)) {
    const separator = token.indexOf(":");
    if (separator <= 0) {
      terms.push(token);
      continue;
    }

    const field = token.slice(0, separator).toLowerCase();
    const value = token.slice(separator + 1);
    if (value.length === 0) {
      unknown.push(token);
      continue;
    }

    if (field === "kind" || field === "in") {
      const kind = value.toLowerCase().replace(/s$/, "") as SearchSubjectKind;
      if (KINDS.includes(kind)) kinds.push(kind);
      else unknown.push(token);
    } else if (field === "project") {
      projectId = value as ProjectId;
    } else {
      unknown.push(token);
    }
  }

  return {
    text: terms.join(" "),
    kinds,
    projectId,
    unknownTokens: unknown,
  };
}

/** `scanSearchQuery` with the default kind filled in for the dialog. */
export function parseSearchQuery(
  raw: string,
  advanced: boolean,
): ParsedSearchQuery {
  const scanned = scanSearchQuery(raw, advanced);
  return {
    ...scanned,
    kinds: scanned.kinds.length > 0 ? scanned.kinds : DEFAULT_SEARCH_KINDS,
  };
}

