/** Escape character for the `LIKE` patterns built from user text. */
const LIKE_ESCAPE = "\\";

/**
 * A `LIKE` pattern matching `text` literally as a substring: `%`, `_` and the
 * escape character itself are ordinary characters in a query, never wildcards.
 */
function containsPattern(text: string): string {
  const escaped = text.replace(/[\\%_]/g, (char) => `${LIKE_ESCAPE}${char}`);
  return `%${escaped}%`;
}

/**
 * Case-insensitive literal substring match over the denormalised content
 * column. Deliberately simple — the index is a convenience layer, not a search
 * engine, and the tenant filter is what actually matters here.
 */
export async function searchDocuments(
  input: SearchQueryInput,
): Promise<Page<SearchIndexRow>> {
  const db = getDb();
  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };

  const filters = compact(
    orgPredicate(searchIndex.orgId, input.orgId),
    sql`${searchIndex.content} LIKE ${containsPattern(input.q)} ESCAPE ${LIKE_ESCAPE}`,
    input.kinds.length === 0
      ? undefined
      : inArray(searchIndex.subjectKind, [...input.kinds]),
    input.projectId === undefined
      ? undefined
      : eq(searchIndex.projectId, input.projectId),
  );

  const total = db
    .select({ value: count() })
    .from(searchIndex)
    .where(and(...filters))

