/**
 * ADR 0007: the query language, the plan gate and how documents are written.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

function query(tenant: Tenant, q: string, extra: Record<string, unknown> = {}) {
  return searchService.search(tenant.actors.member, {
    orgId: tenant.org.id,
    q,
    kinds: ["issue"],
    limit: 25,
    cursor: null,
    ...extra,
  } as never);
}

async function post(tenant: Tenant, issueId: string, body: string) {
  return commentService.createComment(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issueId as never,
    body,
    parentId: null,
    mentionedUserIds: [],
  });
}

describe("search query language", () => {
  it("treats a colon as an ordinary character on a plan without advanced_search", async () => {
    const t = await createTenant("qstarter", "starter");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Release 2: hotfix" }),
    );

    const hits = await query(t, "Release 2: hotfix");
    expect(hits.total).toBe(1);
    expect(hits.items[0]).toMatchObject({ id: issue.id });
  });

  it("does not interpret kind: without advanced_search, and only searches issues", async () => {
    const t = await createTenant("qgrowth", "growth");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "kind:comment flaky title" }),
    );
    await post(t, issue.id, "flaky comment body");

    expect((await query(t, "kind:comment flaky")).total).toBe(1);
    const all = await query(t, "flaky", { kinds: ["issue", "comment", "project"] });
    expect(all.total).toBe(1);
    expect(all.items.every((hit) => hit.kind === "issue")).toBe(true);
  });

  it("applies kind:, in: and project: tokens on advanced_search workspaces", async () => {
    const t = await createTenant("qenterprise", "enterprise");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "flaky pipeline" }),
    );
    const comment = await post(t, issue.id, "so flaky today");

    const byKind = await query(t, "kind:comment flaky");
    expect(byKind.items.map((hit) => hit.id)).toEqual([comment.id]);

    const byAlias = await query(t, "in:comments flaky");
    expect(byAlias.items.map((hit) => hit.id)).toEqual([comment.id]);

    const both = await query(t, "kind:issue kind:comment flaky");
    expect(both.total).toBe(2);

    const scoped = await query(t, `project:${t.project.id} flaky`, {
      kinds: ["issue", "comment"],
    });
    expect(scoped.total).toBe(2);

    const elsewhere = await query(t, "project:prj_nowhere flaky", {
      kinds: ["issue", "comment"],
    });
    expect(elsewhere.total).toBe(0);

    const ignored = await query(t, "status:done flaky kind:");
    expect(ignored.items.map((hit) => hit.id)).toEqual([issue.id]);
  });

  it("finds comments through the projectId filter", async () => {
    const t = await createTenant("qprojectid", "growth");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "carrier" }),
    );
    const comment = await post(t, issue.id, "scoped remark");

    const hits = await searchService.search(t.actors.member, {
      orgId: t.org.id,
      q: "scoped remark",
      kinds: ["comment"],
      projectId: t.project.id,
      limit: 25,
      cursor: null,
    });
    // growth: comments are not searchable, so the plan gate wins.
    expect(hits.total).toBe(0);

    const e = await createTenant("qprojectid2", "enterprise");
    const eIssue = await issueService.createIssue(
      e.actors.member,
      issueInput(e.org.id, e.project.id, { title: "carrier" }),
    );
    const eComment = await post(e, eIssue.id, "scoped remark");
    const eHits = await searchService.search(e.actors.member, {
      orgId: e.org.id,
      q: "scoped remark",
      kinds: ["comment"],
      projectId: e.project.id,
      limit: 25,
      cursor: null,
    });
    expect(eHits.items.map((hit) => hit.id)).toEqual([eComment.id]);
    expect(comment.id).not.toBe(eComment.id);
  });

  it("matches % and _ literally", async () => {
    const t = await createTenant("qliteral", "starter");
    const pct = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Reach 100% coverage" }),
    );
    await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Unrelated thing" }),
    );
    const snake = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "use snake_case here" }),
    );
    await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "use snake case here" }),
    );
    const slash = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "path a\\b done" }),
    );

    expect((await query(t, "100%")).items.map((hit) => hit.id)).toEqual([pct.id]);
    expect((await query(t, "snake_case")).items.map((hit) => hit.id)).toEqual([snake.id]);
    expect((await query(t, "a\\b")).items.map((hit) => hit.id)).toEqual([slash.id]);
    expect((await query(t, "%")).total).toBe(1);
  });
});

describe("search documents", () => {
  it("re-indexes an edited comment", async () => {
    const t = await createTenant("qedit", "enterprise");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "edit host" }),
    );
    const comment = await post(t, issue.id, "before wording");
    await commentService.updateComment(t.actors.member, {
      orgId: t.org.id,
      commentId: comment.id,
      body: "after wording",
    });

    const fresh = await query(t, "after wording", { kinds: ["comment"], projectId: t.project.id });
    expect(fresh.items.map((hit) => hit.id)).toEqual([comment.id]);
    expect((await query(t, "before wording", { kinds: ["comment"] })).total).toBe(0);
  });

  it("serves reindex requests for comments and projects, and skips archived issues", async () => {
    const t = await createTenant("qreindex", "enterprise");
    const issue = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "reindex host" }),
    );
    const comment = await post(t, issue.id, "reindexable remark");
    const archived = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "retired host" }),
    );
    await issueService.archiveIssue(t.actors.member, t.org.id, archived.id);

    const envelope = {
      orgId: t.org.id,
      actorId: t.userIds.admin,
      occurredAt: new Date().toISOString() as never,
    };
    const request = (subjectKind: "issue" | "comment" | "project", subjectId: string) =>
      emit("search.reindex_requested", { ...envelope, subjectKind, subjectId });

    // Simulate an index clean-up by dropping the documents first.
    await searchService.removeFromIndex(t.org.id, "comment", comment.id);
    await searchService.removeFromIndex(t.org.id, "project", t.project.id);
    expect((await query(t, "reindexable", { kinds: ["comment"] })).total).toBe(0);

    await request("comment", comment.id);
    await request("project", t.project.id);
    await request("issue", archived.id);

    const comments = await query(t, "reindexable", { kinds: ["comment"], projectId: t.project.id });
    expect(comments.items.map((hit) => hit.id)).toEqual([comment.id]);
    const projects = await query(t, t.project.name, { kinds: ["project"] });
    expect(projects.items.map((hit) => hit.id)).toEqual([t.project.id]);
